  ParametersValue.RappPrtlStreamer.Setting.StreamerInternalClockIntervalMs = 10;
  ParametersValue.RappPrtlStreamer.Setting.StreamerPrescaler = 19;

  for(uint32_t i0 = 0; i0 < 200; i0++) {
    ParametersValue.RappPrtlStreamer.Setting.StreamerParameterIds[i0] = 65535;
  }


  ParametersValue.RappBaseBoardStartup.Monitoring.BoardStartupReport.OverallResult = 1;
  ParametersValue.RappBaseBoardStartup.Monitoring.BoardStartupReport.ExecutionTimeUs = 0;
  ParametersValue.RappBaseBoardStartup.Monitoring.BoardStartupReport.Wiz850io.ConnectionResult = 1;
